	},
	[324501011] = {
		speaker = "",
		prefab_name = "",
		content = "我带上玄问，与当归一同登上城楼。与我离开时一样，城外的原野上聚满了荒兽，只是荒兽群内部似乎发生了骚乱，四面八方的荒兽都往一个地点聚集过去。",
		id = 324501011
	},
	[324501012] = {
		speaker = "",
		prefab_name = "",
		content = "我朝那荒兽汇聚的中心望去，一眼就认出了那抹纷飞的水蓝色剑光，脸色瞬间阴沉下来，扭头看向快步朝我走来秋丹。",
		id = 324501012
	},
