	[324502012] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "又要战斗，又不想受伤，没有这么好的事。",
		id = 324502012
	},
	[324502013] = {
		speaker = "我",
		prefab_name = "",
		content = "那要拼命总得有个理由吧？",
		id = 324502013
	},
	[324502014] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "因为你说了。",
		id = 324502014
	},
	[324502015] = {
		speaker = "我",
		prefab_name = "",
		content = "我……",
		id = 324502015
	},
	[324502016] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "而且，燕沂城，我们住过，是好地方。",
		id = 324502016
	},
	[324502017] = {
		speaker = "",
		prefab_name = "",
		content = "我看着望舒，不知道该说什么。如果换成别人，我也许会夸一句「深明大义」，但她说这句话，也许真的只是因为她对燕沂城印象不错。",
		id = 324502017
	},
	[324502018] = {
		speaker = "",
		prefab_name = "",
		content = "短暂的沉默中，我注意到跟在我们后面的边军和武罗意味深长的眼神，叹了口气，放弃了继续和望舒纠结这个问题。",
		id = 324502018
	},
	[324502019] = {
		speaker = "我",
		prefab_name = "",
		content = "……你歇会儿吧，一会儿我们去囚云山。",
		id = 324502019
	},
	[324502020] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "去囚云山是——",
		id = 324502020
	},
	[324502021] = {
		speaker = "我",
		prefab_name = "",
		content = "对。后土不在，我来启动机关。",
		id = 324502021
	},
	[324502022] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "那为什么还要等？",
		id = 324502022
	},
	[324502023] = {
		speaker = "我",
		prefab_name = "",
		content = "要考虑到其他影响啊……我跟秋丹简单聊聊。",
		id = 324502023
	},
	[324502024] = {
		speaker = "",
		prefab_name = "",
		content = "望舒点点头，到校场边缘坐下，我愣了愣，快步走到她边上。",
		id = 324502024
	},
	[324502025] = {
		speaker = "我",
		prefab_name = "",
		content = "你干嘛？",
		id = 324502025
	},
	[324502026] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "休息。",
		id = 324502026
	},
	[324502027] = {
		speaker = "我",
		prefab_name = "",
		content = "胡闹。回客房睡会儿。",
		id = 324502027
	},
	[324502028] = {
		speaker = "",
		prefab_name = "",
		content = "望舒抬头看着我，这回我不惯着她，也盯着她看。她没说话，身子前倾想要站起身，可双腿一晃，险些没保持住平衡。",
		id = 324502028
	},
	[324502029] = {
		speaker = "",
		prefab_name = "",
		content = "我连忙扶住她，这才发现她的身体都因为接连的战斗而有些僵硬。",
		id = 324502029
	},
	[324502030] = {
		speaker = "我",
		prefab_name = "",
		content = "我背你回去。",
		id = 324502030
	},
	[324502031] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "？",
		id = 324502031
	},
	[324502032] = {
		speaker = "",
		prefab_name = "",
		content = "不容分说，我卸下剑匣，借搀扶的动作将望舒背起来，然后提起剑匣，走向客房。",
		id = 324502032
	},
	[324502033] = {
		speaker = "",
		prefab_name = "",
		content = "她还是没说话，甚至没有挣扎的动作，接受得似乎过于自然。我觉得有些不对劲，扭头看了眼她搭在我肩上的侧脸，却是已经闭眼睡着了。",
		id = 324502033
	},
	[324502034] = {
		speaker = "",
		prefab_name = "",
		content = "将她放到床上，盖好被褥，看着她平静的睡相，我有些焦躁的心也慢慢平静下来。",
		id = 324502034
	},
	[324502035] = {
		speaker = "我",
		prefab_name = "",
		content = "……一会儿我还是自己去囚云山吧。",
		id = 324502035
	},
	[324502036] = {
		speaker = "",
		prefab_name = "",
		content = "来到秋丹的办公室，我直白地说明了这十天里我的经历和回来的目的。从听到大荒要与虚恒重连开始，他的神情就有些呆滞。",
		id = 324502036
	},
	[324502037] = {
		speaker = "我",
		prefab_name = "",
		content = "……怎么了，觉得有什么问题吗？",
		id = 324502037
	},
	[324502038] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "不……不是……只是不知道该说什么……",
		id = 324502038
	},
	[324502039] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "现在回归感觉很合理，也是必要的，但就是这么多人念叨了这么多年的事，忽然就……",
		id = 324502039
	},
	[324502040] = {
		speaker = "我",
		prefab_name = "",
		content = "如果没有你们这么多年的坚守，大荒的局面早就不是今天这个样子，虚恒面临的灾祸，也会严重到不可估量的地步。",
		id = 324502040
	},
	[324502041] = {
		speaker = "我",
		prefab_name = "",
		content = "这不是什么一蹴而就的事，是安定了虚恒的人，和守护大荒的人，所有努力水到渠成的结果。",
		id = 324502041
	},
	[324502042] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "是啊，水到渠成。杜仲将军是对的，一直以来的坚持，没有白费。",
		id = 324502042
	},
	[324502043] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "只是可惜……定远老哥，等了一辈子，就差这么几天……",
		id = 324502043
	},
	[324502044] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "罢了，罢了，不说这些。",
		id = 324502044
	},
	[324502045] = {
		speaker = "",
		prefab_name = "",
		content = "秋丹摘下眼镜，抹了两下眼睛，铺开桌上剑门关以南的地图。",
		id = 324502045
	},
	[324502046] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "你刚才提到两地合并可能引发的地质问题，应该是想说这个吧？",
		id = 324502046
	},
	[324502047] = {
		speaker = "我",
		prefab_name = "",
		content = "对。尤其是剑门关外荒兽聚集，万一地震导致城墙破裂甚至倒塌，那麻烦可就大了。",
		id = 324502047
	},
	[324502048] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "这倒不必担心。大荒也不是什么宜居之地，地震不算少见，建材又稀缺，所以各类房屋建筑，要造就按最牢靠的标准造。",
		id = 324502048
	},
	[324502049] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "至于剑门关，荒兽攻城的破坏力可比地震大多了，这里所有建筑都是军事化标准。我再调些工程兵加固一下也就是了。",
		id = 324502049
	},
	[324502050] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "真正麻烦的，另有其事……",
		id = 324502050
	},
	[324502051] = {
		speaker = "我",
		prefab_name = "",
		content = "返乡的问题吗？",
		id = 324502051
	},
	[324502052] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "没错……现在前线战事吃紧，这消息可以是好事，也可以是坏事。还有你说的信息口径，保密问题……",
		id = 324502052
	},
	[324502053] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "这些，我与燕沂城的牧守希文大人商量商量吧。",
		id = 324502053
	},
	[324502054] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "你打算一个人去囚云山？",
		id = 324502054
	},
	[324502055] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯，两侧囚云山基本是对称的环境，你帮我弄个能上去的载具就行了，大后方应该没什么别的危险……",
		id = 324502055
	},
	[324502056] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "未必。",
		id = 324502056
	},
	[324502057] = {
		speaker = "",
		prefab_name = "",
		content = "我打了个颤，难以置信地回头看着站在门口的望舒。",
		id = 324502057
	},
	[324502058] = {
		speaker = "我",
		prefab_name = "",
		content = "你怎么这么快起来了？",
		id = 324502058
	},
	[324502059] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我听见了，你说你要一个人去囚云山。",
		id = 324502059
	},
	[324502060] = {
		speaker = "我",
		prefab_name = "",
		content = "你偷听？！",
		id = 324502060
	},
	[324502061] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "不是，客房里你自己说的。",
		id = 324502061
	},
	[324502062] = {
		speaker = "我",
		prefab_name = "",
		content = "……你不是睡着了吗？怎么会知道我说了什么？",
		id = 324502062
	},
	[324502063] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……知道就是知道。",
		id = 324502063
	},
	[324511001] = {
		speaker = "车夫",
		prefab_name = "",
		content = "到了。",
		id = 324511001
	},
	[324511002] = {
		speaker = "",
		prefab_name = "",
		content = "车辆停在囚云山脚下，引擎的轰鸣渐渐停止。我与望舒下了车，与这位曾带我们从剑门关去燕沂城的车夫打了声招呼。",
		id = 324511002
	},
	[324511003] = {
		speaker = "我",
		prefab_name = "",
		content = "你开车可真是收放自如，上回走走停停，这回过弯都不带减速的。",
		id = 324511003
	},
	[324511004] = {
		speaker = "车夫",
		prefab_name = "",
		content = "哈哈，听说你们赶时间，马力就开足些。",
		id = 324511004
	},
	[324511005] = {
		speaker = "车夫",
		prefab_name = "",
		content = "要不要我在山脚下等你们？",
		id = 324511005
	},
	[324511006] = {
		speaker = "我",
		prefab_name = "",
		content = "不用了。无论顺不顺利，都不差那点返程的时间……",
		id = 324511006
	},
	[324511007] = {
		speaker = "",
		prefab_name = "",
		content = "与车夫告别后，望舒提着我登上了囚云山——因为她没学过御剑，所以只能用这种比较粗暴的办法。",
		id = 324511007
	},
	[324511008] = {
		speaker = "",
		prefab_name = "",
		content = "与无常姐妹说的一样，囚云山两侧几乎是对称的布局，肉眼可见的所有景观造物都很熟悉。",
		id = 324511008
	},
	[324511009] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "这里有些危险。",
		id = 324511009
	},
	[324511010] = {
		speaker = "我",
		prefab_name = "",
		content = "我知道，山上有机关，但我知道怎么走，没事的。",
		id = 324511010
	},
	[324511011] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你来过？",
		id = 324511011
	},
	[324511012] = {
		speaker = "我",
		prefab_name = "",
		content = "这你就不知道了吧，虚恒那边也有个囚云山。这几天我就在那里学习操作对接机关的方法，偶尔也会上山下山的。",
		id = 324511012
	},
	[324511013] = {
		speaker = "我",
		prefab_name = "",
		content = "要是对山里的机关都不熟悉，那在山里就白住了。",
		id = 324511013
	},
	[324511014] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我知道了……你往后站。",
		id = 324511014
	},
	[324511015] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么，还是不放心？",
		id = 324511015
	},
	[324511016] = {
		speaker = "",
		prefab_name = "",
		content = "望舒敲了一下我的脑袋，指了指前方的山道，然后拔出剑把我拦在身后。我抬头望去，只见一位老人从山道上闲庭信步地走下来。",
		id = 324511016
	},
	[324511017] = {
		speaker = "我",
		prefab_name = "",
		content = "！！",
		id = 324511017
	},
	[324511018] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "是一个人。我们不知道他是什么东西，反正就是人的样貌。是他在指挥荒兽。",
		id = 324511018
	},
	[324511019] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "不知道名字，是个老人，白须白发，穿一身锦袍。",
		id = 324511019
	},
	[324511020] = {
		speaker = "我",
		prefab_name = "",
		content = "是你……",
		id = 324511020
	},
	[324511021] = {
		speaker = "老人",
		prefab_name = "",
		content = "见人先拔剑，小姑娘是不是太没礼貌了？",
		id = 324511021
	},
	[324511022] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你和相柳很像，不算人。",
		id = 324511022
	},
	[324511023] = {
		speaker = "老人",
		prefab_name = "",
		content = "你呢，小伙子？女伴说话这么冲，你就默许了？",
		id = 324511023
	},
	[324511024] = {
		speaker = "我",
		prefab_name = "",
		content = "谁可信谁不可信，我还分得清楚。先不说普通人根本上不了囚云山，就你这副不慌不忙的反应，是自己人就有鬼了。",
		id = 324511024
	},
	[324511025] = {
		speaker = "老人",
		prefab_name = "",
		content = "说来说去，就可惜你们先见了相柳。那小子桀骜乖戾，和你们定然不会相处得很愉快。",
		id = 324511025
	},
	[324511026] = {
		speaker = "我",
		prefab_name = "",
		content = "屠戮无辜可不能称作相处……你是谁，和相柳是什么关系？",
		id = 324511026
	},
	[324511027] = {
		speaker = "共工",
		prefab_name = "",
		content = "我叫共工，和他没关系。只不过同在大荒生长，认识而已。",
		id = 324511027
	},
	[324511028] = {
		speaker = "我",
		prefab_name = "",
		content = "所以，你和他一样都能操控荒兽？你也是荒兽吗？",
		id = 324511028
	},
	[324511029] = {
		speaker = "共工",
		prefab_name = "",
		content = "人就是野兽，但没人愿意承认，我也不例外。",
		id = 324511029
	},
	[324511030] = {
		speaker = "共工",
		prefab_name = "",
		content = "就算是相柳，性格再冲动也知道冷静，荒兽可不会……哦，忘记问了，他死了么？",
		id = 324511030
	},
	[324511031] = {
		speaker = "我",
		prefab_name = "",
		content = "藏得挺好。",
		id = 324511031
	},
	[324511032] = {
		speaker = "共工",
		prefab_name = "",
		content = "是么……看来你们不太擅长对付这种——",
		id = 324511032
	},
	[324511033] = {
		speaker = "",
		prefab_name = "",
		content = "仿佛身体瞬间幻化成一道虚影，望舒在我反应过来前已经冲到了共工面前，提剑便砍。",
		id = 324511033
	},
	[324511034] = {
		speaker = "",
		prefab_name = "",
		content = "然而共工只是站在原地，手里的长杖轻轻点地，一股无形的波动自触点扩散开来。望舒剑势转攻为守，斩在那波动上，才让它显露出太虚能量的本貌。",
		id = 324511034
	},
	[324511035] = {
		speaker = "",
		prefab_name = "",
		content = "这一击发生只在一瞬，望舒便被震回原处。虽然没有受伤，但依然让我心头一沉，这还是我第一次见她在一对一正面交手中落入下风。",
		id = 324511035
	},
	[324511036] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "他比相柳强很多。",
		id = 324511036
	},
	[324511037] = {
		speaker = "我",
		prefab_name = "",
		content = "你有这实力，不去燕沂城兴风作浪，到山上堵我们做什么？",
		id = 324511037
	},
	[324511038] = {
		speaker = "共工",
		prefab_name = "",
		content = "嗯……这里面有太多误会。",
		id = 324511038
	},
	[324511039] = {
		speaker = "共工",
		prefab_name = "",
		content = "首先，我对你们的什么城什么关都没兴趣。灭了燕沂城又能怎么样？等你们把大荒连回虚恒，又会有人过来喊着要收复失地。",
		id = 324511039
	},
	[324511040] = {
		speaker = "我",
		prefab_name = "",
		content = "你是怎么知道的……你要阻止我们吗？",
		id = 324511040
	},
	[324511041] = {
		speaker = "共工",
		prefab_name = "",
		content = "我没理由那么做。就像你们——如果谁都对外来者抱有敌意，你觉得你们，盖亚，作为「外来者」，还能允许存在吗？",
		id = 324511041
	},
	[324511042] = {
		speaker = "我",
		prefab_name = "",
		content = "……你说什么？！",
		id = 324511042
	},
	[324511043] = {
		speaker = "共工",
		prefab_name = "",
		content = "呵呵，看来你知道的也不是很多。总之这是其一，其二，那座城里也有些麻烦的人在，就算我要出手，也不会那么轻松。",
		id = 324511043
	},
	[324511044] = {
		speaker = "",
		prefab_name = "",
		content = "我皱了皱眉，脑海中快速过了一遍在大荒遇到过的所有人，硬是没想出一个与共工说法匹配的对象。",
		id = 324511044
	},
	[324511045] = {
		speaker = "共工",
		prefab_name = "",
		content = "我们的时间都很宝贵，就不说闲话了。你们能从虚恒过来，身份必然不一般。我找你们，只有一件事。",
		id = 324511045
	},
	[324511046] = {
		speaker = "共工",
		prefab_name = "",
		content = "让人类退到剑门关以南，大荒可以不会再有战事。",
		id = 324511046
	},
	[324511047] = {
		speaker = "我",
		prefab_name = "",
		content = "当年荒兽打到剑门关的时候，怎么不见你出面？",
		id = 324511047
	},
	[324511048] = {
		speaker = "共工",
		prefab_name = "",
		content = "谈判之前，总要确认对方有谈判的资本。",
		id = 324511048
	},
	[324511049] = {
		speaker = "共工",
		prefab_name = "",
		content = "这些年大荒还算安稳，要不是杜仲带人跑到泰泽，也不会有现在的烂摊子。",
		id = 324511049
	},
	[324511050] = {
		speaker = "共工",
		prefab_name = "",
		content = "哦，对了，现在被困在雁门关的军队，你如果同意我的提议，我会放了他们。",
		id = 324511050
	},
	[324511051] = {
		speaker = "我",
		prefab_name = "",
		content = "两个问题。",
		id = 324511051
	},
	[324511052] = {
		speaker = "共工",
		prefab_name = "",
		content = "你说。",
		id = 324511052
	},
	[324511053] = {
		speaker = "我",
		prefab_name = "",
		content = "第一，十多天过去了，雁门关还是受困的状态，我不觉得你有轻易消灭他们的手段。",
		id = 324511053
	},
	[324511054] = {
		speaker = "我",
		prefab_name = "",
		content = "就像你说的，「谈判之前，总要确认对方有谈判的资本」。",
		id = 324511054
	},
	[324511055] = {
		speaker = "共工",
		prefab_name = "",
		content = "嗯，是这个道理。第二个问题呢？",
		id = 324511055
	},
	[324511056] = {
		speaker = "我",
		prefab_name = "",
		content = "第二，与虎谋皮通常没有好结果。",
		id = 324511056
	},
	[324511057] = {
		speaker = "我",
		prefab_name = "",
		content = "也像你说的，人尚且有野兽的一面，何况真正的野兽。我凭什么相信你？",
		id = 324511057
	},
	[324511058] = {
		speaker = "",
		prefab_name = "",
		content = "共工挑起白眉，无所谓地点点头。",
		id = 324511058
	},
	[324511059] = {
		speaker = "共工",
		prefab_name = "",
		content = "我只提供一个选择。至于选不选、信不信，都是你的事。",
		id = 324511059
	},
	[324511060] = {
		speaker = "共工",
		prefab_name = "",
		content = "那就这样吧，你们上山，我下山，有机会再见面了。",
		id = 324511060
	},
	[324521001] = {
		speaker = "",
		prefab_name = "",
		content = "共工下山了，我和望舒没有阻拦。",
		id = 324521001
	},
	[324521002] = {
		speaker = "我",
		prefab_name = "",
		content = "……应该说他没有妨碍我们，已经是不幸中的万幸了。",
		id = 324521002
	},
	[324521003] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "他说的，退到剑门关以南，你不考虑一下？",
		id = 324521003
	},
	[324521004] = {
		speaker = "我",
		prefab_name = "",
		content = "没法考虑。还记得我跟你说过的「智骸」吗？他们最大的威胁就是暗中活动，等你发现他们的时候，他们已经开始行动了，防不胜防。",
		id = 324521004
	},
	[324521005] = {
		speaker = "我",
		prefab_name = "",
		content = "答应共工，就等于失去了对荒兽活动的监控。如果它们再次南下，我们就没有战略缓冲了，剑门关就会面临现在雁门关的困境，整个后方都不安全。",
		id = 324521005
	},
	[324521006] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "所以，你不相信共工。",
		id = 324521006
	},
	[324521007] = {
		speaker = "我",
		prefab_name = "",
		content = "这话是什么意思……你也知道他很危险，是敌人。",
		id = 324521007
	},
	[324521008] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "荒兽是杀不完的。",
		id = 324521008
	},
	[324521009] = {
		speaker = "",
		prefab_name = "",
		content = "我对这个判断没有异议。荒兽能够使用域外能量，共工甚至直接提到了盖亚是「外来者」，它们的来历几乎已经可以确认，就是盖亚之外。",
		id = 324521009
	},
	[324521010] = {
		speaker = "我",
		prefab_name = "",
		content = "……人类也不会放弃生存，这不是妥协的理由。",
		id = 324521010
	},
	[324521011] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你进一尺，他退一丈，最后还是妥协。",
		id = 324521011
	},
	[324521012] = {
		speaker = "我",
		prefab_name = "",
		content = "那就让他先把那一丈退出去。",
		id = 324521012
	},
	[324521013] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "如果做得到，也行。",
		id = 324521013
	},
	[324521014] = {
		speaker = "我",
		prefab_name = "",
		content = "你不会没自信了吧……",
		id = 324521014
	},
	[324521015] = {
		speaker = "",
		prefab_name = "",
		content = "望舒淡淡看了我一眼，虽然她没有直接回答，但我知道多少被我说中了。或者说她有这样的心态反倒让我松了口气，知道顾虑，才会知道保护自己。",
		id = 324521015
	},
	[324521016] = {
		speaker = "我",
		prefab_name = "",
		content = "人类经历过的所谓「不可战胜」的困难实在多到数不过来了。它们大多没有完美的解决方法，就像你说的，最后只能妥协。",
		id = 324521016
	},
	[324521017] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "既然知道结果，为什么还——",
		id = 324521017
	},
	[324521018] = {
		speaker = "我",
		prefab_name = "",
		content = "但妥协总是最后一步。",
		id = 324521018
	},
	[324521019] = {
		speaker = "",
		prefab_name = "",
		content = "就像望舒平时对我讲道理时喜欢做的那样，我也轻轻敲了一下她的脑袋，然后冲木然摸着自己头顶的她笑了笑。",
		id = 324521019
	},
	[324521020] = {
		speaker = "我",
		prefab_name = "",
		content = "人类就是这脾气，在看到结果之前，总想多要一点。实在没办法了，再想该怎么折中。",
		id = 324521020
	},
	[324521021] = {
		speaker = "我",
		prefab_name = "",
		content = "这也是无奈养成的习惯。要想生存，要想有尊严，就得一遍遍地向那些挤轧我们的存在发起挑战。",
		id = 324521021
	},
	[324521022] = {
		speaker = "我",
		prefab_name = "",
		content = "盖亚是人建起来的，大荒是盖亚的一部分。我管它荒兽是从哪儿来的，不守规矩，就得从人类的地盘上滚出去。",
		id = 324521022
	},
	[324521023] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "狠话说得挺顺口。",
		id = 324521023
	},
	[324521024] = {
		speaker = "我",
		prefab_name = "",
		content = "共工都走了，说点狠话找补找补气势总行吧。",
		id = 324521024
	},
	[324521025] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……既然你这么想杀他，如果有机会，我会告诉你。",
		id = 324521025
	},
	[324521026] = {
		speaker = "我",
		prefab_name = "",
		content = "呃……这就说得太远了。先上山吧。",
		id = 324521026
	},
	[324522001] = {
		speaker = "我",
		prefab_name = "",
		content = "……好了，已经过了机关区域，前面没有了。",
		id = 324522001
	},
	[324522002] = {
		speaker = "",
		prefab_name = "",
		content = "我抹了一把虚汗，心有余悸地回头看了眼山道。",
		id = 324522002
	},
	[324522003] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "「我知道怎么走，没事的。」",
		id = 324522003
	},
	[324522004] = {
		speaker = "我",
		prefab_name = "",
		content = "……哈哈，这不是因为有你在嘛。出于对望舒同学的信任，我断定不会有事的。",
		id = 324522004
	},
	[324522005] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你要是太依赖我，为了你的安全，我不会让你出门了。",
		id = 324522005
	},
	[324522006] = {
		speaker = "我",
		prefab_name = "",
		content = "呃没有没有，开开玩笑……",
		id = 324522006
	},
	[324522007] = {
		speaker = "我",
		prefab_name = "",
		content = "只是没想到大荒这边的机关这么狠。这么比起来，无常姐妹守的那段山道简直就是游乐场了。",
		id = 324522007
	},
	[324522008] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "若是为了阻拦荒兽上山，这种程度还算正常。",
		id = 324522008
	},
	[324522009] = {
		speaker = "我",
		prefab_name = "",
		content = "总之，谢谢。要不是你跟我过来，不知道还要费多少事。",
		id = 324522009
	},
	[324522010] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你说这个，我不喜欢。",
		id = 324522010
	},
	[324522011] = {
		speaker = "",
		prefab_name = "",
		content = "望舒摇了摇头，「不喜欢」似乎并非只是说说而已，她收了剑，径自往山顶走去。",
		id = 324522011
	},
	[324522012] = {
		speaker = "",
		prefab_name = "",
		content = "我苦笑一声，心里又泛起一阵暖意，快步跟上她，与她并排走着。只是如此，便让人心安。",
		id = 324522012
	},
	[324531001] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "这个，和那个，感觉不搭。",
		id = 324531001
	},
	[324531002] = {
		speaker = "",
		prefab_name = "",
		content = "视线随着望舒的手指移动，从眼前的花田移到不远处的秋霖宫，我叹了口气，短暂的感动烟消云散。",
		id = 324531002
	},
	[324531003] = {
		speaker = "我",
		prefab_name = "",
		content = "我知道这里环境不如瑶池，但我们应该不是特意来看风景的。",
		id = 324531003
	},
	[324531004] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "住在这里的人，肯定也知道不搭。",
		id = 324531004
	},
	[324531005] = {
		speaker = "我",
		prefab_name = "",
		content = "……你是说后土其实不喜欢这里。",
		id = 324531005
	},
	[324531006] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "要想种花，这里条件不好。喜欢鲜艳，住处却很幽深。",
		id = 324531006
	},
	[324531007] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "她不是不喜欢这里，她心里有矛盾。",
		id = 324531007
	},
	[324531008] = {
		speaker = "",
		prefab_name = "",
		content = "我没见过后土，或者说只见过无常姐妹的那幅简笔画，对后土并不了解，也不知道望舒这句语气近乎陈述的判断是否可靠。",
		id = 324531008
	},
	[324531009] = {
		speaker = "",
		prefab_name = "",
		content = "我只看得出，这座秋霖宫内外都是我熟悉的样子，甚至比无常姐妹的住处更加朴实整洁。",
		id = 324531009
	},
	[324531010] = {
		speaker = "我",
		prefab_name = "",
		content = "不愧是高人隐居的地方啊。",
		id = 324531010
	},
	[324531011] = {
		speaker = "",
		prefab_name = "",
		content = "结构虽然近似，但毕竟居住的人不同，房间的布局也有些不同。望舒对屋里的东西不感兴趣，直奔机关室而去，看到我挨个检查房间，才又折了回来。",
		id = 324531011
	},
	[324531012] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你在找什么？",
		id = 324531012
	},
	[324531013] = {
		speaker = "我",
		prefab_name = "",
		content = "后土留下来的东西。",
		id = 324531013
	},
	[324531014] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "什么东西？",
		id = 324531014
	},
	[324531015] = {
		speaker = "我",
		prefab_name = "",
		content = "我不知道。也许是什么手册，也许是什么笔记……",
		id = 324531015
	},
	[324531016] = {
		speaker = "我",
		prefab_name = "",
		content = "大荒绝通过去快八十年了，天知道这边有没有什么新发现，或者事故。后土应该也没想到自己会被困，所以有些没公开的消息也很正常。",
		id = 324531016
	},
	[324531017] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "那，你找到什么了？",
		id = 324531017
	},
	[324531018] = {
		speaker = "我",
		prefab_name = "",
		content = "……这个。",
		id = 324531018
	},
	[324531019] = {
		speaker = "",
		prefab_name = "",
		content = "眼前大概是后土的卧室，我一进门就看到桌上摆着一本纸质的笔记本。虽然私自翻看很不礼貌，但这时候也顾不上这么多了——",
		id = 324531019
	},
	[324531020] = {
		speaker = "我",
		prefab_name = "",
		content = "……",
		id = 324531020
	},
	[324531021] = {
		speaker = "",
		prefab_name = "",
		content = "顺着书签带翻到最新一页，我看着几乎占满整页纸的「要」「死」「了」三个夸张的大字，以及右下角字号正常字形娟秀的日期落款，陷入了深深的沉思。",
		id = 324531021
	},
	[324531022] = {
		speaker = "我",
		prefab_name = "",
		content = "……你记不记得秋丹说大军北征是哪天？",
		id = 324531022
	},
	[324531023] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "二月十五。",
		id = 324531023
	},
	[324531024] = {
		speaker = "我",
		prefab_name = "",
		content = "那没错了……",
		id = 324531024
	},
	[324531025] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "写了什么？",
		id = 324531025
	},
	[324531026] = {
		speaker = "",
		prefab_name = "",
		content = "我摇摇头，装作什么都没看到，又往前翻了几页，也没找到什么有用的信息。",
		id = 324531026
	},
	[324531027] = {
		speaker = "我",
		prefab_name = "",
		content = "（这世界果然是个巨大的草台班子。）",
		id = 324531027
	},
	[324531028] = {
		speaker = "",
		prefab_name = "",
		content = "于是我合上笔记本，转头朝机关室走去。",
		id = 324531028
	},
	[324531029] = {
		speaker = "我",
		prefab_name = "",
		content = "……就是这个。",
		id = 324531029
	},
	[324531030] = {
		speaker = "",
		prefab_name = "",
		content = "来到机关室最深处的操作台边，仔细检查了一遍所有机关，我终于松了口气。",
		id = 324531030
	},
	[324531031] = {
		speaker = "",
		prefab_name = "",
		content = "就和无常姐妹描述的一样，两座秋霖宫的布局完全一致，大荒这侧的机关也没有年久失修的迹象，甚至感觉保养得更加细致。",
		id = 324531031
	},
	[324531032] = {
		speaker = "我",
		prefab_name = "",
		content = "望舒，我要……",
		id = 324531032
	},
	[324531033] = {
		speaker = "",
		prefab_name = "",
		content = "我回过头，望舒正闲散地靠在门边，听到我喊她，静静地转过头来看着我。",
		id = 324531033
	},
	[324531034] = {
		speaker = "",
		prefab_name = "",
		content = "我原本想让她离开房间，因为按照无常姐妹的嘱咐，机关启动的时候，机关室里不能有外人……可望舒真的算外人吗？我需要担心她做出什么事呢？",
		id = 324531034
	},
	[324531035] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你要？",
		id = 324531035
	},
	[324531036] = {
		speaker = "我",
		prefab_name = "",
		content = "没事。你到我这儿来吧，小心不要碰到屋里的东西。",
		id = 324531036
	},
	[324531037] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "还需要我帮忙？",
