	[324531043] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "嗯。",
		id = 324531043
	},
	[324531044] = {
		speaker = "",
		prefab_name = "",
		content = "望舒慵懒的语调成功击碎了我的仪式感，不过也让我刚生出的紧张情绪快速消退下去。",
		id = 324531044
	},
	[324531045] = {
