	},
	[324531068] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我们没动。",
		id = 324531068
	},
	[324531069] = {
		speaker = "",
		prefab_name = "",
		content = "望舒摇了摇头，拉住我的手，带我踏入太虚。我回头看向身后，只有缺了一面墙的机关室孤零零地悬浮在虚空当中。",
		id = 324531069
	},
	[324531070] = {
		speaker = "",
		prefab_name = "",
		content = "而在我们身后更远处，也有一片云霭环绕的群山缓缓驶近。",
		id = 324531070
	},
	[324531071] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "从你打开阀门的时候开始，我们就已经到这里了。",
