	},
	[324661021] = {
		speaker = "雀儿",
		prefab_name = "",
		content = "陵光代理可是了不起的大人物，平时我们都没机会见到呢。能让她来咱们村，金乌姐姐就很了不起啦。",
		id = 324661021
	},
	[324661022] = {
		speaker = "大树",
		prefab_name = "",
		content = "金、金乌姐姐……我……我替我娘，还有我，一、一起感谢你。",
		id = 324661022
	},
	[324661023] = {
		speaker = "",
		prefab_name = "",
		content = "大树朝金乌鞠了一躬，金乌连忙扶起他，心里却感觉到一阵舒坦。",
		id = 324661023
	},
	[324661024] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "你做手术那天，乌再去看你~",
		id = 324661024
	},
	[324671001] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "金乌啊，慢点走。",
		id = 324671001
	},
	[324671002] = {
		speaker = "",
		prefab_name = "",
		content = "解决完村民们的委托，金乌正要离村，却听到洪村长远远喊住了她。金乌连忙跑过去，好让老人家少走两步路。",
		id = 324671002
	},
	[324671003] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "村长爷爷，还有别的事要交给乌吗？",
		id = 324671003
	},
	[324671004] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "嘿呦……你这忙东忙西的，还没忙活够呢。",
		id = 324671004
	},
	[324671005] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "来，我代表村里大伙儿给你送点小零嘴儿，拿着路上吃吧。",
		id = 324671005
	},
	[324671006] = {
		speaker = "",
		prefab_name = "",
		content = "洪村长递给金乌一只竹篮，里面装满了各种大槐树村本地的零食点心，堆得像座小山。",
		id = 324671006
	},
	[324671007] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "这……这也太多了吧，乌一个人吃不完。",
		id = 324671007
	},
	[324671008] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "吃不完，拿去送给你那些个朋友也好啊。山里的东西没城里精细，但味道差不了。",
		id = 324671008
	},
	[324671009] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "大家也太客气了，平时乌下山，大家也给乌送东西吃。",
		id = 324671009
	},
	[324671010] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "呵呵，那不是因为，你每次下山，都像这样帮大家的忙嘛。",
		id = 324671010
	},
	[324671011] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "都是些顺手的小事啦，而且有时候还会搞砸……",
		id = 324671011
	},
	[324671012] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "哎，话不能这么说，你看着是些小事，可落在大伙儿头上，那都是实打实的要紧事。",
		id = 324671012
	},
	[324671013] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "生老病死，家国社稷，人这一辈子，能遇到几回大事？不就是这一桩桩「小事」，决定了日子过得是好是坏嘛。",
		id = 324671013
	},
	[324671014] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "所以啊，可不要小瞧了你平时对大伙儿的照顾。就算是那些「搞砸」的事，有你帮忙，看似坏了五成，可没你帮忙，得坏十成。",
		id = 324671014
	},
	[324671015] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "大家都是实在人，就算心疼那五成坏，也不会不认你那五成好啊。",
		id = 324671015
	},
	[324671016] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "……原来大家都不怪乌吗？",
		id = 324671016
	},
	[324671017] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "行善就该论心不论迹，否则做好事还得为结果瞻前顾后，谁又会愿意站出来呢？",
		id = 324671017
	},
	[324671018] = {
		speaker = "洪村长",
		prefab_name = "",
		content = "这世上啊，多些像你这样的好孩子，我这样的老骨头，心里都踏实很多咧。",
		id = 324671018
	},
	[324701001] = {
		speaker = "工头",
		prefab_name = "",
		content = "哎，小领导……",
		id = 324701001
	},
	[324701002] = {
		speaker = "",
		prefab_name = "",
		content = "我和金乌正准备继续北上，工头忽然神秘兮兮地喊住了我，苦着脸，一副申冤无门的样子。",
		id = 324701002
	},
	[324701003] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么，有事不先跟重明说？",
		id = 324701003
	},
	[324701004] = {
		speaker = "工头",
		prefab_name = "",
		content = "小姐也不知道啊。但您不一样，听说您是「上面」来的大人物，兴许能给我们说说呢。",
		id = 324701004
	},
	[324701005] = {
		speaker = "我",
		prefab_name = "",
		content = "你哪儿听来的……什么事？",
		id = 324701005
	},
	[324701006] = {
		speaker = "工头",
		prefab_name = "",
		content = "停工的原因呀。您说句公道话，我们的施工速度，那都看得见摸得着。上次您来工地视察的时候，那边那几幢楼都还只有个地基呢。",
		id = 324701006
	},
	[324701007] = {
		speaker = "工头",
		prefab_name = "",
		content = "通知上只说什么「不可抗力」、「考虑到安全问题」……这不明不白的，大家怎么接受嘛？",
		id = 324701007
	},
	[324701008] = {
		speaker = "我",
		prefab_name = "",
		content = "通知这么写自然有这么写的道理。否则能说明白的事，藏着掖着白受猜疑，有什么好处呢？",
		id = 324701008
	},
	[324701009] = {
		speaker = "工头",
		prefab_name = "",
		content = "我当然也知道不方便说，但大家伙儿都决定要留下了，心里还是想敞亮些。",
		id = 324701009
	},
	[324701010] = {
		speaker = "工头",
		prefab_name = "",
		content = "否则万一停工背后有什么要紧原因，我们不知道，坏了上面的事，那就得不偿失了。",
		id = 324701010
	},
	[324701011] = {
		speaker = "我",
		prefab_name = "",
		content = "……倒不用有这方面的顾虑。最近确实可能会发生一些地质变动，但原因比较复杂，关系到一项影响力不比轩辕计划小的事情。",
		id = 324701011
	},
	[324701012] = {
		speaker = "我",
		prefab_name = "",
		content = "这件事和良工集团无关，硬要说，你们算是受到波及的一方……但停工以后可以再复工，那件事却迫在眉睫了。",
		id = 324701012
	},
	[324701013] = {
		speaker = "工头",
		prefab_name = "",
		content = "真有大事啊……",
		id = 324701013
	},
	[324701014] = {
		speaker = "我",
		prefab_name = "",
		content = "你明白重要性就好，不要乱传。",
		id = 324701014
	},
	[324701015] = {
		speaker = "工头",
		prefab_name = "",
		content = "懂的，懂的，现在这个当口，如果真出了事，挨骂的是我们，可不敢乱说话。",
		id = 324701015
	},
	[324701016] = {
		speaker = "",
		prefab_name = "",
		content = "工头单手叉腰，望着连片的工地，一声长叹。我能在他眼中看到最朴实的、对自己劳动成果的不舍。",
		id = 324701016
	},
	[324701017] = {
		speaker = "工头",
		prefab_name = "",
		content = "唉，一期工程快完工了，建筑整体还是比较牢靠的，只要不是特别剧烈的地震，应该能扛得住。",
		id = 324701017
	},
	[324701018] = {
		speaker = "工头",
		prefab_name = "",
		content = "可二期就难说了，周边的卫星城，刚按新的城建规划划好地。",
		id = 324701018
	},
	[324701019] = {
		speaker = "我",
		prefab_name = "",
		content = "前期投入应该不算大吧。",
		id = 324701019
	},
	[324701020] = {
		speaker = "工头",
		prefab_name = "",
		content = "成本我不清楚，但如果受损太严重，现在的城建方案可能就要作废了。临时改方案，这个麻烦可不小。",
		id = 324701020
	},
	[324701021] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯……那叫上重明一起，我们也去二期工程的工地看看吧。",
		id = 324701021
	},
	[324711001] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……这是工地？",
		id = 324711001
	},
	[324711002] = {
		speaker = "",
		prefab_name = "",
		content = "到了二期工程的一处工地，重明愣愣地看着眼前的「废墟」，回头严肃地盯着满脸尴尬的工头。",
		id = 324711002
	},
	[324711003] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "为什么施工区内连建筑残骸都没清理干净？",
		id = 324711003
	},
	[324711004] = {
		speaker = "工头",
		prefab_name = "",
		content = "因为一期进度比较快，二期很早就被催着开始，我又不方便说工期紧张，就先弄几块地基打个样……",
		id = 324711004
	},
	[324711005] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "这有什么不方便说的？",
		id = 324711005
	},
	[324711006] = {
		speaker = "工头",
		prefab_name = "",
		content = "这……我说做不了，那可有的是人觉得自己做得了呢……",
		id = 324711006
	},
	[324711007] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……我们良工集团什么时候也有这种急功近利的风气了？",
		id = 324711007
	},
	[324711008] = {
		speaker = "",
		prefab_name = "",
		content = "工头汗流浃背，只能一个劲地点头认错。我观察了一会儿工地，笑着对重明招了招手。",
		id = 324711008
	},
	[324711009] = {
		speaker = "我",
		prefab_name = "",
		content = "二期现在的情况，我看未必是坏事。",
		id = 324711009
	},
	[324711010] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "你就别安慰大家了，小哥，这些残骸都有坍塌破损的风险，很容易影响到在建的建筑，现在处理太麻烦了。",
		id = 324711010
	},
	[324711011] = {
		speaker = "我",
		prefab_name = "",
		content = "这些「在建」的建筑，大多还只有地基呢。规划中它们是居民楼写字楼，实际上就一定要是吗？",
		id = 324711011
	},
	[324711012] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "你的意思是？",
		id = 324711012
	},
	[324711013] = {
		speaker = "我",
		prefab_name = "",
		content = "碉堡。",
		id = 324711013
	},
	[324711014] = {
		speaker = "",
		prefab_name = "",
		content = "我捡起几块石头，快速搭了一座碉堡。原本只是想简单做个示意，可上手后娴熟的感觉让我自己都有些意外。",
		id = 324711014
	},
	[324711015] = {
		speaker = "我",
		prefab_name = "",
		content = "工期短，见效快，改造简单，结构强度就不用我多说了。",
		id = 324711015
	},
	[324711016] = {
		speaker = "工头",
		prefab_name = "",
		content = "还能这样吗？",
		id = 324711016
	},
	[324711017] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "感觉确实可行。模块化施工的话，事后拆除地上的部分也不复杂。",
		id = 324711017
	},
	[324711018] = {
		speaker = "工头",
		prefab_name = "",
		content = "但这么大的改动，是不是得向上面请示一下？",
		id = 324711018
	},
	[324711019] = {
		speaker = "我",
		prefab_name = "",
		content = "让舆昊老板点头，不是让他难堪么？",
		id = 324711019
	},
	[324711020] = {
		speaker = "工头",
		prefab_name = "",
		content = "不是舆昊老板，我是说天理阁，技术顾问——「上面」。",
		id = 324711020
	},
	[324711021] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "……就知道是你想出来的点子。",
		id = 324711021
	},
	[324711022] = {
		speaker = "我",
		prefab_name = "",
		content = "嘿嘿，你要是有别的好点子，我也可以帮忙传达一下嘛。",
		id = 324711022
	},
	[324711023] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我没什么点子……算你歪打正着吧，修碉堡，还不赖。",
		id = 324711023
	},
	[324711024] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "但现在因为停工通知，良工集团处在风口浪尖上，你们就算要做，也别大张旗鼓地找五岛要资源。",
		id = 324711024
	},
	[324711025] = {
		speaker = "",
		prefab_name = "",
		content = "我环视四周的废墟，了然地耸耸肩。",
		id = 324711025
	},
	[324711026] = {
		speaker = "我",
		prefab_name = "",
		content = "就地取材，不算难事。",
		id = 324711026
	},
	[324722001] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "呼……这样就算是找齐了。",
		id = 324722001
	},
	[324722002] = {
		speaker = "",
		prefab_name = "",
		content = "确认好所有打算重复利用的建材的位置，重明松了口气，虽然遭遇了一些波折，但她看上去比之前要兴奋了不少。",
		id = 324722002
	},
	[324722003] = {
		speaker = "我",
		prefab_name = "",
		content = "心情不错啊。",
		id = 324722003
	},
	[324722004] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "是好一些了……",
		id = 324722004
	},
	[324722005] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "原本一期工程那边没什么头绪，刚到二期工地的时候，看到满地的废墟也有些沮丧。",
		id = 324722005
	},
	[324722006] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "现在总算感觉自己做了一些实事，心里踏实了不少……",
		id = 324722006
	},
	[324722007] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "不说我了。小哥啊，你是怎么想出这个办法的？",
		id = 324722007
	},
	[324722008] = {
		speaker = "我",
		prefab_name = "",
		content = "下意识吧……可能以前有过类似的经验？",
		id = 324722008
	},
	[324722009] = {
		speaker = "",
		prefab_name = "",
		content = "我耸耸肩，想到怀信口中过去的那个我，忽然觉得自己这随口一说可能并非没有可能。",
		id = 324722009
	},
	[324722010] = {
		speaker = "我",
		prefab_name = "",
		content = "……说点实在的吧，其实所有问题都有一个通行的解决思路，简单来说就是搞清楚自己想要的到底是什么，或者能不能完全实现最理想的结果。",
		id = 324722010
	},
	[324722011] = {
		speaker = "我",
		prefab_name = "",
		content = "如果不能——而且现实往往就是不能，那么就把目标拆分一下，列个优先级，暂时忽略掉那些低优先级的目标。",
		id = 324722011
	},
	[324722012] = {
		speaker = "我",
		prefab_name = "",
		content = "比如说这次，保住二期工程城建布局的优先级要高于现有的这些地基，而维持原状则不是必要的。",
		id = 324722012
	},
	[324722013] = {
