	},
	[936011130] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "我才没害羞！只是觉得没必要！",
		id = 936011130
	},
	[936011131] = {
		speaker = "我",
		prefab_name = "",
		content = "我记得某人说过……音乐是情感的奔流，声音这么小也能叫奔流吗？",
		id = 936011131
	},
	[936011132] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "好啊……唱就唱！谁怕谁！你跟我过来！",
		id = 936011132
	},
	[936011133] = {
		speaker = "",
		prefab_name = "",
		content = "荷鲁斯拉着我穿过狂热的人群，来到舞台的前方。",
		id = 936011133
	},
	[936011134] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "你也跟我一起唱，拿着！",
		id = 936011134
	},
	[936011135] = {
		speaker = "",
