	[936011147] = {
		speaker = "我",
		prefab_name = "",
		content = "我只是在想……你这次能坚持多久？",
		id = 936011147
	},
	[936011148] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "什么坚持多久，只要有人陪我一起练习，保证没问题！",
		id = 936011148
	},
	[936011149] = {
		speaker = "我",
		prefab_name = "",
		content = "那么问题就来了，谁会陪你练呢？我记得上次某人花了两周都没能把招募信息发出去，乐队也不了了之了。",
		id = 936011149
	},
	[936011150] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "那……那你帮我找人总行了吧！就算不当乐队成员，你也能当制作人啊！",
		id = 936011150
	},
	[936011151] = {
		speaker = "我",
		prefab_name = "",
		content = "制作人啊……你也知道，我的工作很多。",
		id = 936011151
	},
	[936011152] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "你之前说的那什么移转观测……我陪你去就行了吧？",
		id = 936011152
	},
	[936011153] = {
		speaker = "我",
		prefab_name = "",
		content = "那你的坚持呢？",
		id = 936011153
	},
	[936011154] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "未来是由自己创造的。这是我自己的选择，所以没关系。",
		id = 936011154
	},
	[936011155] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "再说，你也带我来演唱会了，我可不喜欢欠人情……",
		id = 936011155
	},
	[936011156] = {
		speaker = "我",
		prefab_name = "",
		content = "那就这么定了，明天我们隐科组见。",
		id = 936011156
	},
	[936011157] = {
		speaker = "我",
		prefab_name = "",
		content = "早上好，辛苦了。",
		id = 936011157
	},
	[936011158] = {
		speaker = "",
		prefab_name = "",
		content = "第二天，荷鲁斯如约等在了隐科组的门口，我朝她招了招手，递上一杯可乐。",
		id = 936011158
	},
	[936011159] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "先说好，仅此一次啊。",
		id = 936011159
	},
	[936011160] = {
		speaker = "我",
		prefab_name = "",
		content = "仅此一轮吧，万一隐科组她们不止一次实验，总不能中途换人吧？",
