	},
	[936011161] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "嘿，你还想得寸进尺！\n算了算了，都答应了，下不为例……",
		id = 936011161
	},
	[936011162] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "早啊两位……怎么站在隐科组门口打情骂俏的？",
		id = 936011162
	},
	[936011163] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "谁打情骂俏了！要不是这家伙如此执着，我才不会来呢！",
		id = 936011163
	},
	[936011164] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "唔？",
		id = 936011164
	},
	[936011165] = {
		speaker = "我",
		prefab_name = "",
		content = "你要的移转观测志愿者，我可是费了好一番心思拉来的。",
		id = 936011165
	},
	[936011166] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "了不起啊，管理员，连荷鲁斯都能搞定，夸夸你。",
		id = 936011166
	},
	[936011167] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "来吧，马上开始，不浪费你们时间。",
		id = 936011167
	},
	[936011168] = {
		speaker = "",
		prefab_name = "",
		content = "我们来到明显大了一圈的移转观测舱前，海姆达尔从正在调试的面板上抬起头，简单打了个招呼。",
		id = 936011168
	},
	[936011169] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "在外面磨蹭什么呢，赶快进来开始啊。",
		id = 936011169
	},
	[936011170] = {
		speaker = "",
		prefab_name = "",
		content = "正聊着的时候，荷鲁斯的催促从观测舱里冒了出来。我探头望去，发现她早已躺在位置上，此刻正左扭右扭地调整着姿势。",
		id = 936011170
	},
	[936011171] = {
		speaker = "我",
		prefab_name = "",
		content = "来了来了。\n总之，一会儿见。",
		id = 936011171
	},
	[936011172] = {
		speaker = "",
		prefab_name = "",
		content = "向海姆达尔和大国主示意过后，我也钻进观测舱，与荷鲁斯并肩躺下。",
		id = 936011172
	},
	[936011173] = {
		speaker = "",
		prefab_name = "",
		content = "随着机器启动，我也再度感受到那股熟悉的力量，牵引着我逐渐模糊的意识飞向另一端……",
		id = 936011173
	},
	[936011174] = {
		speaker = "",
		prefab_name = "",
		content = "或许是已经适应了移转观测，我感觉醒来的间隔特别短暂。当我睁开眼时，映入眼帘是依稀有些熟悉，却一时找不到头绪的休息室。",
		id = 936011174
	},
	[936011175] = {
		speaker = "我",
		prefab_name = "",
		content = "唔……这是哪？荷鲁斯呢？",
		id = 936011175
	},
	[936011176] = {
		speaker = "",
		prefab_name = "",
		content = "我向四处张望，却并未发现荷鲁斯的身影。正当我起身打算寻找的时候，一位身穿制服的女性向我走来。",
		id = 936011176
	},
	[936011177] = {
		speaker = "接待员",
		prefab_name = "",
		content = "欢迎，制作人先生。其他人都已经去隔间准备了，要我领您过去吗？",
		id = 936011177
	},
	[936011178] = {
		speaker = "我",
		prefab_name = "",
		content = "……？\n啊，是在跟我说话吗？",
		id = 936011178
	},
	[936011179] = {
		speaker = "接待员",
		prefab_name = "",
		content = "是的，您有什么疑问吗？\n如果您喝多了……或者身体不舒服，也可以再休息一下。",
		id = 936011179
	},
	[936011180] = {
		speaker = "我",
		prefab_name = "",
		content = "没有的，只是确认一下。带我过去吧。",
		id = 936011180
	},
	[936011181] = {
		speaker = "",
		prefab_name = "",
		content = "因为之前的移转观测也遇到过一时难以理解的情况，我决定暂且不多纠结，跟随接待员穿过宽大的休息室，中途不忘瞄了一眼她的工牌。",
		id = 936011181
	},
	[936011182] = {
		speaker = "我",
		prefab_name = "",
		content = "（「超感互娱」……所以是第五部门举办的某种活动现场？这跟荷鲁斯的未来又有什么关系呢……）",
		id = 936011182
	},
	[936011183] = {
		speaker = "接待员",
		prefab_name = "",
		content = "就是这边。请您稍等片刻，「摇滚超新星」海选比赛很快就会开始，到时候叫号上场哦。",
		id = 936011183
	},
	[936011184] = {
		speaker = "",
		prefab_name = "",
		content = "接待员将我带到一间隔音良好的包间前，然后就先行告退。当我推开门时，出乎意料的是，里面不仅有荷鲁斯，还有另外几位熟面孔。",
		id = 936011184
	},
	[936011185] = {
		speaker = "奥西里斯",
		prefab_name = "1211ui_story",
		content = "管……制作人，你来啦！",
		id = 936011185
	},
	[936011186] = {
		speaker = "我",
		prefab_name = "",
		content = "小奥西里斯？还有必安、无咎？你们也在？",
		id = 936011186
	},
	[936011187] = {
		speaker = "",
		prefab_name = "",
		content = "我环顾着略显拥挤的房间，以及靠墙摆放的各种乐器，最终将目光落在荷鲁斯身上。但她也只是一耸肩，对于我理解局势没有提供任何帮助。",
		id = 936011187
	},
	[936011188] = {
		speaker = "无咎",
		prefab_name = "1054ui_story",
		content = "果然……我还是会拖大家后腿的吧……",
		id = 936011188
	},
	[936011189] = {
		speaker = "必安",
		prefab_name = "6148ui_story",
		content = "说的什么话，管理员的意思是很高兴你能鼓起勇气如约来参加比赛，对吧？",
		id = 936011189
	},
	[936011190] = {
		speaker = "我",
		prefab_name = "",
		content = "没错没错！只是海选赛而已，我们五个人出手，那还不是小菜一碟！",
		id = 936011190
	},
	[936011191] = {
		speaker = "",
		prefab_name = "",
		content = "在安抚无咎的同时，我赶忙朝荷鲁斯使起眼色，把她单独叫到一边，在墙角交头接耳。",
		id = 936011191
	},
	[936011192] = {
		speaker = "我",
		prefab_name = "",
		content = "你先来的，弄清楚什么情况了吗？",
		id = 936011192
	},
	[936011193] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "嗨，大概就是我们几个组了乐队，来参加海选赛出道，我还是主唱呢。",
		id = 936011193
	},
	[936011194] = {
		speaker = "我",
		prefab_name = "",
		content = "小奥西里斯还能理解，无咎和必安怎么会……",
		id = 936011194
	},
	[936011195] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "无咎和必安？",
		id = 936011195
	},
	[936011196] = {
		speaker = "我",
		prefab_name = "",
		content = "就是一黑一白的那两个修正者，她们本来应该住在虚恒才对啊……",
		id = 936011196
	},
	[936011197] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "你问我，我问谁？反正不都是你这个制作人叫来的？",
		id = 936011197
	},
	[936011198] = {
		speaker = "我",
		prefab_name = "",
		content = "我到底都干了些什么……算了，先不提这个。我们参赛选了什么曲子，你会唱吗？",
		id = 936011198
	},
	[936011199] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "这有什么难的，我是音乐奇才，刚才已经看过谱子了，一遍就会。",
		id = 936011199
	},
	[936011200] = {
		speaker = "我",
		prefab_name = "",
		content = "你就吹吧。",
		id = 936011200
	},
	[936011201] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "嘁，又不是你上台，怂什么！事到临头了，难道你还要退赛？",
		id = 936011201
	},
	[936011202] = {
		speaker = "我",
		prefab_name = "",
		content = "那就……先试试吧。",
		id = 936011202
	},
	[936011203] = {
		speaker = "",
		prefab_name = "",
		content = "看着荷鲁斯信心满满的样子，以及其他人一脸期待的神情，我也没办法反驳荷鲁斯。正巧这时叫到了我们的号码，我只能目送她们一同走向舞台。",
		id = 936011203
	},
	[936011204] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "怎么样，我就说了，我是音乐奇才吧。",
		id = 936011204
	},
	[936011205] = {
		speaker = "",
		prefab_name = "",
		content = "荷鲁斯一脸得意地看向我，只是看过一次谱子就能唱成这样的确值得夸赞，但是……",
		id = 936011205
	},
	[936011206] = {
		speaker = "评委",
		prefab_name = "",
		content = "可以听出你们的歌声中富含感情，但乐器之间毫无配合，甚至就连副歌切换的时机都混乱无比。",
		id = 936011206
	},
	[936011207] = {
		speaker = "评委",
		prefab_name = "",
		content = "以目前的表现来看，我只能遗憾地通知你们，本场比赛的结果是……「不合格」！",
		id = 936011207
	},
	[936011208] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "哈？！",
		id = 936011208
	},
	[936011209] = {
		speaker = "",
		prefab_name = "",
		content = "舞台上的荷鲁斯当场就炸了毛，要不是其他几人拦着，恐怕举着红色叉号的评委立刻就会享受到一记从天而降的掌法。在一片喧嚣与吵闹中，我们的海选赛还是无奈地画上了句号。",
		id = 936011209
	},
	[936011210] = {
		speaker = "",
		prefab_name = "",
		content = "接下来的记忆，就有些模糊了……",
		id = 936011210
	},
	[936011211] = {
