		prefab_name = "1044ui_story",
		content = "呃啊啊啊啊！！！怎么是这种未来啊！",
		id = 936011211
	},
	[936011212] = {
		speaker = "",
		prefab_name = "",
		content = "当我在观测舱里睁开眼时，身旁的荷鲁斯正一脸不满地吵闹着。闻声打开舱门的大国主和海姆达尔一脸不解，将询问的目光投向我。",
		id = 936011212
	},
