	},
	[325011047] = {
		speaker = "当归母亲",
		prefab_name = "",
		content = "我去找老包说说。您忙吧，武罗上仙。",
		id = 325011047
	},
	[325011048] = {
		speaker = "",
		prefab_name = "",
		content = "工坊里间的房门被武罗重重拉上，隔绝了外界的所有声光。她将颢铭丢到墙角，仰躺在床上，剑门关与燕沂城的种种景象在脑海中挥之不去。",
