	},
	[325011056] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "要是有这本事，早给边军用了……",
		id = 325011056
	},
	[325011057] = {
		speaker = "",
		prefab_name = "",
		content = "虽然嘴上抱怨了几句，武罗工作起来依然认真，时而在终端上调试各种参数，时而出入库房和工作间，将一些稀奇古怪的元件连接到通讯模块上。",
		id = 325011057
	},
	[325011058] = {
		speaker = "",
		prefab_name = "",
		content = "时间在一次次尝试中飞快流逝，武罗脸上的阴霾也在这样枯燥却踏实的研究中一点点化去。最后她关掉终端，将通讯模块重新揣回兜里。",
		id = 325011058
	},
	[325011059] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "……不出所料，失败了。",
