		id = 325011070
	},
	[325011071] = {
		speaker = "",
		prefab_name = "",
		content = "越想越心烦意乱，武罗抄起布袋子，重新将颢铭塞了进去。又愣愣地看了它半晌，将它背到身后。",
		id = 325011071
	},
	[325011072] = {
		speaker = "武罗",
