		id = 325011078
	},
	[325011079] = {
		speaker = "伯阳",
		prefab_name = "",
		content = "大家初来乍到，不知道您的居所，也不知道该怎么联系您，所以边走边问找到这里，唐突打扰，还请见谅。",
		id = 325011079
	},
	[325011080] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "铸剑师吗……那算是同门了，不用客气，进来坐坐？",
