	[325011081] = {
		speaker = "伯阳",
		prefab_name = "",
		content = "盛情心领了。不过我们这次来大荒，是应邀协助燕沂城完善城防，算是公务在身，不能耽搁太久。",
		id = 325011081
	},
	[325011082] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "哦……我听人说过南边有支援调过来，原来你们就是。",
		id = 325011082
	},
	[325011083] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
