	},
	[325011084] = {
		speaker = "伯阳",
		prefab_name = "",
		content = "这种工作，我早就熟稔于心，就不劳烦您操心了。您作为铸剑师一脉的话事人，虚恒那边还有更重要的事等您去做。",
		id = 325011084
	},
	[325011085] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "什么话事人……",
		id = 325011085
	},
	[325011086] = {
