	},
	[325011122] = {
		speaker = "监兵",
		prefab_name = "1069ui_story",
		content = "出什么事了，怎么围在这儿？",
		id = 325011122
	},
	[325011123] = {
		speaker = "伯阳",
		prefab_name = "",
		content = "就是我们铸剑师的事，这位武罗阁下执掌信物，原该是我们一脉的传人……",
		id = 325011123
	},
	[325011124] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "都说几遍了，我没以传人自居，不要突然就把事扔过来……",
		id = 325011124
	},
	[325011125] = {
		speaker = "",
		prefab_name = "",
		content = "眼看两边又要争起来，监兵忙摆了摆手，几句话里他也大概听出来是什么情况了。",
		id = 325011125
	},
	[325011126] = {
