		content = "你们内部的事我弄不明白，但我这会儿有急事要找武罗。",
		id = 325011126
	},
	[325011127] = {
		speaker = "武罗",
		prefab_name = "1077ui_story",
		content = "又有什么事？",
		id = 325011127
	},
	[325011128] = {
		speaker = "监兵",
		prefab_name = "1069ui_story",
		content = "公事，换个地方聊。",
