	},
	[325021017] = {
		speaker = "",
		prefab_name = "",
		content = "监兵扭头朝西边张望片刻，街上只有来往行人，没什么值得注意的地方。他却像是看到了什么似的，兀自点了点头。",
		id = 325021017
	},
	[325021018] = {
		speaker = "监兵",
