		id = 325021018
	},
	[325021019] = {
		speaker = "",
		prefab_name = "",
		content = "脚步踏在落地的枯枝上，踩出一连串细微的碎裂声响。监兵仰头打量着这片枯林，眉头微皱。",
		id = 325021019
	},
	[325021020] = {
