	},
	[325501042] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "谨慎是好，也别时刻绷着。若剑抵至极限，断裂只是一瞬之事。",
		id = 325501042
	},
	[325501043] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "嗯，希望是我多虑了……",
		id = 325501043
	},
	[325501044] = {
		speaker = "",
		prefab_name = "",
		content = "杜仲话音未落，脚下突然传出一阵轻颤。一旁的泰逢瞬间变了脸色，寒芒出鞘的同时，拔高了自己的音量。",
		id = 325501044
	},
	[325501045] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "列阵，注意脚下！",
		id = 325501045
	},
	[325501046] = {
		speaker = "",
		prefab_name = "",
		content = "原本勉强能够立足的地面突然像烂泥一样流淌起来，甚至毫无征兆地向内涡旋，形成一个个旋涡，吸住士兵们的靴底向下拖拽。",
		id = 325501046
	},
	[325501047] = {
		speaker = "",
		prefab_name = "",
		content = "与此同时，风沙也变得更加猛烈，朝军阵迎面扑来，将视野染成一片土黄。刚插下的通讯桩则被连根拔起，在空中打着旋。",
		id = 325501047
	},
	[325501048] = {
		speaker = "",
		prefab_name = "",
		content = "一瞬之间，周围的环境仿佛活了过来，像是大荒突然有了自己的生命与意志，准备张口将它身上这支不速之客整个吞下。",
		id = 325501048
	},
	[325501049] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "后土前辈，你有什么办法吗！",
		id = 325501049
	},
	[325501050] = {
		speaker = "后土",
		prefab_name = "10176ui_story",
		content = "来不及，山河搬运术需要时间。",
		id = 325501050
	},
	[325501051] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "啧……一上来就失了地利啊……",
		id = 325501051
	},
	[325501052] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "敌暗我明，先后撤，到雁门关前重整队形。",
		id = 325501052
	},
	[325501053] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "将无人机放到两翼监测状况，以小队为单位轮换战阵里外位置，轮流上车恢复体力。",
		id = 325501053
	},
	[325501054] = {
		speaker = "",
		prefab_name = "",
		content = "紧要关头，杜仲立刻做出判断，勉强让混乱的阵形开始重整，尽量保持秩序地向后退去。",
		id = 325501054
	},
	[325501055] = {
		speaker = "",
		prefab_name = "",
		content = "但一波未平，一波又起，军队刚离开原先的战术位置，四面八方又传来了连绵不断的荒兽吼声。一群又一群荒兽借着风沙的掩护，开始冲击起撤离的队伍。",
		id = 325501055
	},
	[325501056] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "中了埋伏啊……泰逢，后土，你们前往两翼，务必维持阵形不被冲散。",
		id = 325501056
	},
	[325501057] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "明白，左翼交给我，右边你去。",
		id = 325501057
	},
	[325501058] = {
		speaker = "",
		prefab_name = "",
		content = "因为要面对荒兽的袭击，队伍的撤退速度立刻慢了下来。随着时间推移，流沙的影响进一步显现，军阵几乎已经被完全分割，形成数个被周围旋涡纠缠住，各自为战的小单元。",
		id = 325501058
	},
	[325501059] = {
		speaker = "",
		prefab_name = "",
		content = "若不是泰逢与后土在前面阻拦了荒兽冲击的势头，恐怕军队根本找不到撤退的机会，就会被逐个击破，消失在沙海中。",
		id = 325501059
	},
	[325501060] = {
		speaker = "",
		prefab_name = "",
		content = "好在最终经过一番血战，军队在丢下一部分辅助智械与自动武器掩护后，勉强撤回了雁门关。",
		id = 325501060
	},
	[325501061] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "部队的情况怎么样？",
		id = 325501061
	},
	[325501062] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "撤退及时，折损不大。但大家体力消耗都很严重，损坏的器械，丢下的物资……至少需要休养一阵。",
		id = 325501062
	},
	[325501063] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "最大的问题是我们与后方的通讯完全断绝，没办法将消息传回去。",
		id = 325501063
	},
	[325501064] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "嗯……这下有麻烦了。你看外面。",
		id = 325501064
	},
	[325501065] = {
		speaker = "",
		prefab_name = "",
		content = "泰逢顺着杜仲所指的方向看去，雁门关的外面乌泱泱地围了不知多少荒兽，数量还在随着赶来的荒兽而增多。",
		id = 325501065
	},
	[325501066] = {
		speaker = "",
		prefab_name = "",
		content = "作为连年处于战事一线的剑主，泰逢对这场面并不陌生。但望着只围不攻，时不时接近城墙试探，一遭射击就退远的荒兽，泰逢也皱起了眉。",
		id = 325501066
	},
	[325501067] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "从没听说过它们有智力和战术，今天真是大开眼界……",
		id = 325501067
	},
	[325501068] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "从伏击到现在的围困，我们的对手可是下了一手好棋啊。",
		id = 325501068
	},
	[325501069] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "虽然城中补给充足，但终究是被困死地，需要早做打算了……",
		id = 325501069
	},
	[325501070] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "尽早突围吧，拖久了，等荒兽聚过来，伤亡还会增多。",
		id = 325501070
	},
	[325501071] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "让我和后土前辈今夜去探查情况吧，看看哪里适合突围，还有那个叫共工的家伙在不在附近。",
		id = 325501071
	},
	[325501072] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "嗯，你们注意安全。",
		id = 325501072
	},
	[325501073] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "我会安排人手在城墙上支援。要是情况不对，你们马上撤回来。",
		id = 325501073
	},
	[325501074] = {
		speaker = "",
		prefab_name = "",
		content = "即使夜幕降临，围城的荒兽也依然在孜孜不倦地盯着雁门关。不过在它们未能注意到的角落，两道灵活的黑影轻飘飘地从城墙上跳下。",
		id = 325501074
	},
	[325501075] = {
		speaker = "后土",
		prefab_name = "10176ui_story",
		content = "侦查这种事情，明明交给无人机就好了……",
		id = 325501075
	},
	[325501076] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "既然对手能改变大荒的环境，那种方式风险性太高了。",
		id = 325501076
	},
	[325501077] = {
		speaker = "后土",
		prefab_name = "10176ui_story",
		content = "好吧，总之回去之后还是你去汇报。",
		id = 325501077
	},
	[325501078] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "没问题，我已经习惯了。",
		id = 325501078
	},
	[325501079] = {
		speaker = "后土",
		prefab_name = "10176ui_story",
		content = "那就快点结束吧，总有种不好的预感……",
		id = 325501079
	},
	[325501080] = {
		speaker = "",
		prefab_name = "",
		content = "后土打量着周围的环境，突然将目光停在关隘侧面的山岭中。她眯了眯眼，拦下正隐匿前行的泰逢。",
		id = 325501080
	},
	[325501081] = {
		speaker = "",
		prefab_name = "",
		content = "泰逢转过头，在发现后土仍然一脸凝重地望过去时立刻反应过来，抽出枢变，摆好了战斗姿态。",
		id = 325501081
	},
	[325501082] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "……好眼力。",
		id = 325501082
	},
	[325501083] = {
		speaker = "",
		prefab_name = "",
		content = "白须白发的老人从阴影中走出，周围的荒兽无声地簇拥在他的身边，像是拱卫帝王的亲兵。",
		id = 325501083
	},
	[325501084] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "初次见面，两位。有失远迎，还请见谅。",
		id = 325501084
	},
	[325501085] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "……你能号令荒兽？你是谁？",
		id = 325501085
	},
	[325501086] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "不重要。两位眼下最该做的，是从哪里来，回哪里去。",
		id = 325501086
	},
	[325501087] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "装神弄鬼。我不管你是人，还是荒兽，现在投降，我还能饶你一命。",
		id = 325501087
	},
	[325501088] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "嗯……很有自信。那我多加一条，把你刚说过的话原封不动地带给你们的将军，可好？",
		id = 325501088
	},
	[325501089] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "你找死！",
		id = 325501089
	},
	[325501090] = {
		speaker = "",
		prefab_name = "",
		content = "在老者踱步走来的时候，泰逢突然暴起，挥出枢变直取对方面门。电光石火之间，一柄墨色长剑出鞘，以泰逢都未能完全看清的速度架了上来。",
		id = 325501090
	},
	[325501091] = {
		speaker = "",
		prefab_name = "",
		content = "双方的剑刃在身前碰撞，一时陷入僵持。即使泰逢压上全力，枢变却再难寸进。看着对方自如的神情，泰逢的心沉了下去。",
		id = 325501091
	},
	[325501092] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "这种程度，还不太够。",
		id = 325501092
	},
	[325501093] = {
		speaker = "",
		prefab_name = "",
		content = "老者单手架住泰逢，另一只手往前一推，无形的力量在剑刃交汇处骤然爆发，一口气将泰逢震开，向后趔趄了几步才稳住身形。",
		id = 325501093
	},
	[325501094] = {
		speaker = "",
		prefab_name = "",
		content = "泰逢也不服输，立刻欺身而上，剑刃刺出一个刁钻的角度，直奔对方的肋下而去。老者不慌不忙地调转剑锋，简单地一荡，就将枢变架开，随后顺势一砍——",
		id = 325501094
	},
	[325501095] = {
		speaker = "泰逢",
		prefab_name = "10175ui_story",
		content = "……！",
		id = 325501095
	},
	[325501096] = {
		speaker = "",
		prefab_name = "",
		content = "感受到威胁的泰逢刹住了前冲的势头，脚尖点地跳回原位。直至双方重新站定，她才感觉右臂火辣辣的，用手一摸，已是一片殷红。",
		id = 325501096
	},
	[325501097] = {
		speaker = "",
		prefab_name = "",
		content = "不出五招，泰逢就已经落入下风，但对方剑势未停，她也只能继续迎上，勉力支撑着对方的进攻，身上也多出一道又一道细碎的血痕。",
		id = 325501097
	},
	[325501098] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "打算一起来吗？",
		id = 325501098
	},
	[325501099] = {
		speaker = "",
		prefab_name = "",
		content = "两人激战之时，老者身边的空间突然扭曲了起来，周围的空气被压缩成浑浊的球体，凝至极限时再猛然撞向他。",
		id = 325501099
	},
	[325501100] = {
		speaker = "",
		prefab_name = "",
		content = "老者冷哼一声，反手汇聚起惊人的能量。剧烈的爆发在他身侧炸开，冲击波将三人强行分开，重新拉开了距离。",
		id = 325501100
	},
	[325501101] = {
