	},
	[325522028] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "哦……你们是来找他的？",
		id = 325522028
	},
	[325522029] = {
		speaker = "我",
		prefab_name = "",
		content = "剑门关前没见你出手，原来躲在后面对付一个老兵么？",
		id = 325522029
	},
	[325522030] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "省省吧，我要是不杀他，他连全尸都留不下来。",
		id = 325522030
	},
	[325522031] = {
		speaker = "",
		prefab_name = "",
		content = "共工抬了抬手指，定远旁边浮起一只板条箱，径直甩向我们。金乌眉毛一竖，飞身上前拔剑就劈。",
		id = 325522031
	},
	[325522032] = {
		speaker = "",
		prefab_name = "",
		content = "长阳的炽焰穿透板条箱，金乌大叫一声「不好」，只见板条箱猛然爆炸，里面竟全是炸药。好险金乌退得算快，但也搞得灰头土脸。",
		id = 325522032
	},
	[325522033] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "如果你们是来给他收尸的，我不拦着。有一人守一城的勇气，至少值得入土为安。",
		id = 325522033
	},
	[325522034] = {
		speaker = "",
		prefab_name = "",
		content = "我点点头，回头给无咎和必安使了个眼色。她们小心地靠过去，见共工果然没有阻拦，这才抬起定远的遗体，为他轻轻把眼合拢，带去安葬。",
		id = 325522034
	},
	[325522035] = {
		speaker = "",
		prefab_name = "",
		content = "等她们走远，我才回头看向共工。刚才空气里那一丝缓和的气氛也再度凝重起来。",
		id = 325522035
	},
	[325522036] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "想不到你还会对人类共情。",
		id = 325522036
	},
	[325522037] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "我们的差别，倒没有你想象得那么大。",
		id = 325522037
	},
	[325522038] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "退一步说，我和他并没有利益纠纷，不管施予什么，我都不会有负担。",
		id = 325522038
	},
	[325522039] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "现在和我有纠纷的是你们，所以我是来提议的……给你们最后一次和平解决问题的机会。",
		id = 325522039
	},
	[325522040] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "还是那套让人类退回剑门关以南的说法？",
		id = 325522040
	},
	[325522041] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "条件依旧。你们退出去，犯不着再打来打去。",
		id = 325522041
	},
	[325522042] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "现在大荒已经和虚恒重连，你不觉得这个条件没什么吸引力了吗？",
		id = 325522042
	},
	[325522043] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "虚恒……我不在乎你们怎么想，我只说我需要什么。",
