	},
	[325522044] = {
		speaker = "共工",
		prefab_name = "10180ui_story",
		content = "泰泽、囚云山、现在……我没有赶尽杀绝，已经仁至义尽了。要怎么回答是你们的事，只要考虑清楚后果就行。",
		id = 325522044
	},
	[325522045] = {
		speaker = "",
		prefab_name = "",
		content = "身边的金乌已经有些按捺不住，三番五次地朝我递着眼神，但看着明显有恃无恐的共工，我还是轻轻朝她摇了摇头。",
		id = 325522045
	},
	[325522046] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "阁下的口气，倒真是不小啊。",
		id = 325522046
	},
	[325522047] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "但要说到商谈，山人以为，阁下给出的诚意倒还欠了一点。",
		id = 325522047
	},
	[325522048] = {
