	},
	[325522049] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "大荒接入虚恒，正好给留在大荒的子民一个回家的选择。按你的条件来算，应是利大于弊，此为其一。",
		id = 325522049
	},
	[325522050] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "至于现在你以寡敌众，真动起手来胜负犹未可知，同样算不得诚意，此为其二。",
		id = 325522050
	},
	[325522051] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "而说到雁门关，大军情况未知，只听你一面之词便说没有赶尽杀绝，在下恐难信服，此为其三。",
		id = 325522051
	},
	[325522052] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "以上种种，究竟何为诚意，倒还不好说吧。",
