	[325591077] = {
		speaker = "",
		prefab_name = "",
		content = "与三人对峙的穷奇似乎也认出了无咎和必安，威胁性地发出一阵阵低吼，与三人绕着圈对峙，互相寻找着可能的破绽。",
		id = 325591077
	},
	[325591078] = {
