		id = 325601001
	},
	[325601002] = {
		speaker = "",
		prefab_name = "",
		content = "虽然我们解决了几批袭来的荒兽，但一缕缕墨色的能量依然笼罩在我们的周围，化成新的荒兽堵住包围的缺口。",
		id = 325601002
	},
	[325601003] = {
