	},
	[325801021] = {
		speaker = "我",
		prefab_name = "",
		content = "哪些衣服是给当归的，我选出来。",
		id = 325801021
	},
	[325801022] = {
		speaker = "当归母亲",
		prefab_name = "",
		content = "不用……穿在谁身上都一样，都是……咱们的孩子。",
		id = 325801022
	},
	[325801023] = {
		speaker = "",
		prefab_name = "",
		content = "说完，当归母亲头也不回地走了，有些瘦弱的背影很快消失在了人群之中。",
		id = 325801023
	},
	[325801024] = {
		speaker = "希文",
		prefab_name = "",
		content = "是啊，都是咱们的孩子。",
		id = 325801024
	},
	[325801025] = {
		speaker = "",
		prefab_name = "",
		content = "人群熙攘，每个人心里都装着一两个名字，每个名字背后都站着许多人。",
		id = 325801025
	},
	[325811001] = {
		speaker = "希文",
		prefab_name = "",
		content = "虽然一开始说是自愿报名，但是我看基本都来了，不管能不能选上，我都向各位致敬。",
		id = 325811001
	},
	[325811002] = {
		speaker = "",
		prefab_name = "",
		content = "燕沂城的校场上，黑压压站了一地人，都是来报名参加救援队选拔的。",
		id = 325811002
	},
	[325811003] = {
		speaker = "希文",
		prefab_name = "",
		content = "这次任务的目的，你们应该也都知道一二。可谓是难度大、时间紧、任务重。",
		id = 325811003
	},
	[325811004] = {
		speaker = "希文",
		prefab_name = "",
		content = "所以这一次的选拔会很严格、很全面，详细的由这位来讲，他会是此行的队长。",
		id = 325811004
	},
	[325811005] = {
		speaker = "我",
		prefab_name = "",
		content = "这次任务，是要北上救援被围困的大军。因此队伍得战斗力强，又要机动灵活，人员在精不在多。",
		id = 325811005
	},
	[325811006] = {
		speaker = "我",
		prefab_name = "",
		content = "作战的主力主要是几位上仙，剑门关一战，大家应该也对他们有所耳闻。",
		id = 325811006
	},
	[325811007] = {
		speaker = "我",
		prefab_name = "",
		content = "但除去北上急袭，沿路的设施、城池也要恢复，这个单靠我们几个人做不到。",
		id = 325811007
	},
	[325811008] = {
		speaker = "我",
		prefab_name = "",
		content = "另外战场情况瞬息万变，难免有应付不及需要支援的时候，还要选一支精锐部队同我们并肩作战。",
		id = 325811008
	},
	[325811009] = {
		speaker = "希文",
		prefab_name = "",
		content = "因此这次是优中选优，尤其单兵作战能力要强，这个必须现场考核，这也是为什么让大家在校场集合。",
		id = 325811009
	},
	[325811010] = {
		speaker = "希文",
		prefab_name = "",
		content = "大家应该都看到眼前这些智械了，它们就是这次的考核内容。",
		id = 325811010
	},
	[325811011] = {
		speaker = "希文",
		prefab_name = "",
		content = "至于要怎么做，我们请#{nickname}#来示范一下。",
		id = 325811011
	},
	[325811012] = {
		speaker = "我",
		prefab_name = "",
		content = "示范称不上，打个样，仅供参考。",
		id = 325811012
	},
	[325812001] = {
		speaker = "",
		prefab_name = "",
		content = "考核开始前，就走了有一半的人，等到考核完全结束的时候，场上还有力气站着的就不多了。",
		id = 325812001
	},
	[325812002] = {
		speaker = "我",
		prefab_name = "",
		content = "最后一个……好，今天的考核到此结束，辛苦大家。",
		id = 325812002
	},
	[325812003] = {
		speaker = "我",
		prefab_name = "",
		content = "考核结果我们会在排名后通知各位，不论最后有没有加入救援队，能到这里来都是好样的。",
		id = 325812003
	},
	[325812004] = {
		speaker = "",
		prefab_name = "",
		content = "等到在场的军士都渐渐散尽，希文才凑到我身边来。",
		id = 325812004
	},
	[325812005] = {
		speaker = "希文",
		prefab_name = "",
		content = "虽然早知道阁下一定好身手，但方才那一下真是叹为观止，难怪能做这么多大事。",
		id = 325812005
	},
	[325812006] = {
		speaker = "希文",
		prefab_name = "",
		content = "你亮过那一手之后，这底下可都议论纷纷按不住了。",
		id = 325812006
	},
	[325812007] = {
		speaker = "我",
		prefab_name = "",
		content = "谬赞了，平时总跟修……上仙们一块行动，总要努力不拖人后腿。",
		id = 325812007
	},
	[325812008] = {
		speaker = "希文",
		prefab_name = "",
		content = "这番测试下来，如何？燕沂城的守军里，可还能选出人来？",
		id = 325812008
	},
	[325812009] = {
		speaker = "我",
		prefab_name = "",
		content = "比我预想的情况还好，不愧是常驻边疆的军队，身经百战。",
		id = 325812009
	},
	[325812010] = {
		speaker = "我",
		prefab_name = "",
		content = "按原先的计划，凑个满编应该没问题，或许还有余。",
