	},
	[325812011] = {
		speaker = "希文",
		prefab_name = "",
		content = "那就好，这也算是一块大石头落地了。",
		id = 325812011
	},
	[325812012] = {
		speaker = "我",
		prefab_name = "",
		content = "这些人，我会尽可能全须全尾地带回来。",
		id = 325812012
	},
	[325812013] = {
		speaker = "希文",
		prefab_name = "",
		content = "……唯有这句话，不管听多少次类似的，每回我都还是愿意说一句：「我信」。",
		id = 325812013
	},
	[325821001] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "当真挤不出来人了吗？",
		id = 325821001
	},
	[325821002] = {
		speaker = "希文",
		prefab_name = "",
		content = "人就这么多，前后几次发兵，哪还有兵力加强布防。",
