	[1109511175] = {
		speaker = "",
		prefab_name = "",
		content = "底下的孩子们却炸开了锅，七嘴八舌叽叽喳喳地要我们多说点，托特拢了拢鬓发，露出有些泛红的耳尖。",
		id = 1109511175
	},
	[1109511176] = {
		speaker = "",
		prefab_name = "",
		content = "回到住处，托特嘴角的笑意仍未散去，眼底却流露出思索之色。",
		id = 1109511176
	},
	[1109511177] = {
		speaker = "我",
		prefab_name = "",
		content = "看来今天这趟行程安排得很对。",
		id = 1109511177
	},
	[1109511178] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "以前……我一直以为在福利学校的日子会是我这辈子最深刻的记忆之一。",
		id = 1109511178
	},
	[1109511179] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "但刚刚见到那些小孩子，听他们问起，我突然觉得那好像是很久以前、很模糊的事了。",
		id = 1109511179
	},
	[1109511180] = {
		speaker = "我",
		prefab_name = "",
		content = "走进了新的生活，旧的痕迹当然会被一天一天地覆盖下去。",
		id = 1109511180
	},
	[1109511181] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "如果我当初没有遇到诺尔薇，没有因为她而认识你，或许我现在也不会翻开新的一页。",
		id = 1109511181
	},
	[1109511182] = {
		speaker = "我",
		prefab_name = "",
		content = "我倒不觉得有这种「如果」。我们走在相似的道路上，或早或晚，总会遇到。",
		id = 1109511182
	},
	[1109511183] = {
		speaker = "我",
		prefab_name = "",
		content = "只要你还是你，我还是我，我们就一定会走到一起。",
		id = 1109511183
	},
	[1109511184] = {
		speaker = "",
		prefab_name = "",
		content = "我们牵着手走进室内，我在床沿坐下，托特顺势面朝我坐到我腿上。",
		id = 1109511184
	},
	[1109511185] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "然后我们也会像今天一样去福利院，又坐在这里说话？",
		id = 1109511185
	},
	[1109511186] = {
		speaker = "我",
		prefab_name = "",
		content = "当然，无论哪条平行线上的你，肯定都会发愁怎么把人生的新一页变成书上的新篇章的。",
		id = 1109511186
	},
	[1109511187] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "说到这个……",
		id = 1109511187
	},
	[1109511188] = {
