		prefab_name = "",
		content = "我还想说什么，却见托特在床上轻轻拍了一下，然后一下站起身来，快步走到了一旁的桌边。",
		id = 1109511188
	},
	[1109511189] = {
		speaker = "我",
		prefab_name = "",
		content = "哎？",
		id = 1109511189
	},
	[1109511190] = {
		speaker = "我",
		prefab_name = "",
		content = "有灵感了？",
		id = 1109511190
	},
	[1109511191] = {
		speaker = "",
		prefab_name = "",
		content = "我跟过去，看到托特调出了终端屏幕，打开文档。",
