	[303021047] = {
		speaker = "",
		prefab_name = "",
		content = "大国主一边凑近打量着瘦长的人影，一边将手指捅入它的面孔中，那模糊的面容像是一团被拨散的水雾，荡起涟漪，没办法凝聚成确凿的形态。",
		id = 303021047
	},
	[303021048] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "薇儿也是……这么近的距离没有发现异常，还需要多历练啊。",
		id = 303021048
	},
	[303021049] = {
		speaker = "我",
		prefab_name = "",
		content = "这样碰它没关系吗？它会不会……突然袭击过来？",
		id = 303021049
	},
	[303021050] = {
