	[938011024] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿话中那快要溢出来的掩饰感，反而加深了我的疑问。我的目光越过她，扫向桌旁的其他人。",
		id = 938011024
	},
	[938011025] = {
