	[938011314] = {
		speaker = "尼娅",
		prefab_name = "",
		content = "哼哼，别担心！为了驱散你们的无聊，尼娅特意准备了这个！",
		id = 938011314
	},
	[938011315] = {
		speaker = "",
		prefab_name = "",
		content = "尼娅话音刚落，门外猛地传出了一声大地震颤般的巨响。我和薇儿、埃什几人快速交换了一个警惕的眼神，随后迅速推开餐厅大门冲了出去。",
		id = 938011315
	},
	[938011316] = {
		speaker = "",
