	[938021002] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "凭空造出这么大个场地……有人看懂这是要比什么了吗？",
		id = 938021002
	},
	[938021003] = {
		speaker = "",
		prefab_name = "",
		content = "接连不断的疑问声从人群中传出。而制造出这场大动静的始作俑者，正站在高处，得意洋洋地俯视着台下。",
